INSERT INTO essay_rubrics (id, question_id, kunci_jawaban, kata_kunci, rubrik_skor) VALUES
('er-0000004-0000-0000-0000-000000000001', 'q4000002-0000-0000-0000-000000000001', 'Wireframe adalah representasi visual sederhana yang menggambarkan struktur, tata letak, dan alur antarmuka suatu produk digital sebelum masuk ke tahap desain visual detail.', ARRAY['wireframe', 'struktur', 'tata letak', 'blueprint', 'antarmuka']::text[], '{"0":"Salah","7":"Ide umum","8":"60% benar","9":"Kurang 1 unsur","10":">=80% kata kunci"}'::jsonb),
('er-0000004-0000-0000-0000-000000000002', 'q4000002-0000-0000-0000-000000000002', 'Wireframe membantu tim memvalidasi struktur, navigasi, dan alur pengguna sejak awal sehingga kesalahan desain dapat ditemukan lebih cepat dan lebih murah untuk diperbaiki.', ARRAY['validasi', 'struktur', 'alur pengguna', 'efisiensi', 'mengurangi kesalahan']::text[], '{"0":"Salah","7":"Ide umum","8":"60% benar","9":"Kurang 1 unsur","10":">=80% kata kunci"}'::jsonb),
('er-0000004-0000-0000-0000-000000000003', 'q4000002-0000-0000-0000-000000000003', 'Information Architecture adalah proses mengorganisasi, menyusun, dan memberi struktur informasi agar mudah ditemukan, dipahami, dan digunakan oleh pengguna.', ARRAY['information architecture', 'struktur informasi', 'organisasi informasi', 'navigasi', 'kemudahan pengguna']::text[], '{"0":"Salah","7":"Ide umum","8":"60% benar","9":"Kurang 1 unsur","10":">=80% kata kunci"}'::jsonb),
('er-0000004-0000-0000-0000-000000000004', 'q4000002-0000-0000-0000-000000000004', '1. Organization System: mengelompokkan informasi. 2. Labeling System: memberi nama yang mudah dipahami. 3. Navigation System: membantu perpindahan antar halaman. 4. Search System: membantu pencarian informasi.', ARRAY['organization', 'labeling', 'navigation', 'search']::text[], '{"0":"Salah","7":"Ide umum","8":"60% benar","9":"Kurang 1 unsur","10":">=80% kata kunci"}'::jsonb),
('er-0000004-0000-0000-0000-000000000005', 'q4000002-0000-0000-0000-000000000005', 'Header berfungsi sebagai area utama yang biasanya berisi logo, identitas situs, dan navigasi untuk membantu pengguna berpindah halaman.', ARRAY['header', 'logo', 'identitas', 'navigasi']::text[], '{"0":"Salah","7":"Ide umum","8":"60% benar","9":"Kurang 1 unsur","10":">=80% kata kunci"}'::jsonb),
('er-0000004-0000-0000-0000-000000000006', 'q4000004-0000-0000-0000-000000000001', 'Hero Section digunakan untuk menyampaikan pesan utama, nilai produk, atau ajakan tindakan pertama yang ingin dilihat pengguna saat membuka halaman.', ARRAY['hero section', 'pesan utama', 'value proposition', 'cta']::text[], '{"0":"Salah","7":"Ide umum","8":"60% benar","9":"Kurang 1 unsur","10":">=80% kata kunci"}'::jsonb),
('er-0000004-0000-0000-0000-000000000007', 'q4000004-0000-0000-0000-000000000002', 'F-Pattern umumnya digunakan pada halaman dengan banyak teks, sedangkan Z-Pattern lebih cocok untuk landing page sederhana yang mengarahkan perhatian pengguna mengikuti pola huruf Z.', ARRAY['f-pattern', 'z-pattern', 'pola membaca', 'teks', 'landing page']::text[], '{"0":"Salah","7":"Ide umum","8":"60% benar","9":"Kurang 1 unsur","10":">=80% kata kunci"}'::jsonb),
('er-0000004-0000-0000-0000-000000000008', 'q4000004-0000-0000-0000-000000000003', 'Proximity adalah prinsip desain yang menempatkan elemen yang saling berhubungan berdekatan agar mudah dipahami sebagai satu kelompok informasi.', ARRAY['proximity', 'jarak', 'pengelompokan', 'keterkaitan']::text[], '{"0":"Salah","7":"Ide umum","8":"60% benar","9":"Kurang 1 unsur","10":">=80% kata kunci"}'::jsonb),
('er-0000004-0000-0000-0000-000000000009', 'q4000004-0000-0000-0000-000000000004', 'Contrast membantu menciptakan hierarki visual sehingga elemen penting lebih mudah ditemukan dan mendapat perhatian pengguna.', ARRAY['contrast', 'hierarki visual', 'perhatian pengguna', 'elemen penting']::text[], '{"0":"Salah","7":"Ide umum","8":"60% benar","9":"Kurang 1 unsur","10":">=80% kata kunci"}'::jsonb),
('er-0000004-0000-0000-0000-000000000010', 'q4000004-0000-0000-0000-000000000005', 'User Flow adalah visualisasi langkah-langkah yang dilalui pengguna untuk mencapai tujuan tertentu saat menggunakan produk digital.', ARRAY['user flow', 'langkah pengguna', 'tujuan', 'alur']::text[], '{"0":"Salah","7":"Ide umum","8":"60% benar","9":"Kurang 1 unsur","10":">=80% kata kunci"}'::jsonb),
('er-0000004-0000-0000-0000-000000000011', 'q4000006-0000-0000-0000-000000000001', 'Decision digunakan untuk menunjukkan titik pengambilan keputusan yang menghasilkan percabangan alur berdasarkan kondisi tertentu.', ARRAY['decision', 'percabangan', 'kondisi', 'keputusan']::text[], '{"0":"Salah","7":"Ide umum","8":"60% benar","9":"Kurang 1 unsur","10":">=80% kata kunci"}'::jsonb),
('er-0000004-0000-0000-0000-000000000012', 'q4000006-0000-0000-0000-000000000002', 'Happy Path adalah alur ideal ketika pengguna berhasil menyelesaikan tugas tanpa hambatan atau kesalahan.', ARRAY['happy path', 'alur ideal', 'berhasil', 'tanpa hambatan']::text[], '{"0":"Salah","7":"Ide umum","8":"60% benar","9":"Kurang 1 unsur","10":">=80% kata kunci"}'::jsonb),
('er-0000004-0000-0000-0000-000000000013', 'q4000006-0000-0000-0000-000000000003', 'Edge Case adalah kondisi khusus atau tidak umum yang tetap perlu dipertimbangkan karena dapat memengaruhi pengalaman pengguna.', ARRAY['edge case', 'kondisi khusus', 'skenario tidak umum', 'pengalaman pengguna']::text[], '{"0":"Salah","7":"Ide umum","8":"60% benar","9":"Kurang 1 unsur","10":">=80% kata kunci"}'::jsonb),
('er-0000004-0000-0000-0000-000000000014', 'q4000006-0000-0000-0000-000000000004', 'Karena Dead End membuat pengguna tidak mengetahui langkah selanjutnya sehingga dapat menyebabkan kebingungan, frustrasi, dan kegagalan menyelesaikan tujuan.', ARRAY['dead end', 'kebingungan', 'frustrasi', 'langkah selanjutnya']::text[], '{"0":"Salah","7":"Ide umum","8":"60% benar","9":"Kurang 1 unsur","10":">=80% kata kunci"}'::jsonb),
('er-0000004-0000-0000-0000-000000000015', 'q4000006-0000-0000-0000-000000000005', 'Crazy 8''s adalah metode ideasi cepat untuk menghasilkan banyak alternatif solusi atau sketsa desain dalam waktu singkat sehingga meningkatkan kreativitas dan eksplorasi ide.', ARRAY['crazy 8''s', 'ideasi', 'kreativitas', 'banyak ide', 'sketsa cepat']::text[], '{"0":"Salah","7":"Ide umum","8":"60% benar","9":"Kurang 1 unsur","10":">=80% kata kunci"}'::jsonb);
